import Foundation
import Security

/// Turns an RSA key generated by Security into the OpenSSH private-key text
/// the rest of Bellterm already imports and stores. The private key never
/// leaves this device and is never logged.
struct RSAKeyMaterial: Equatable {
    var modulus: Data
    var publicExponent: Data
    var privateExponent: Data
    var prime1: Data
    var prime2: Data
    var exponent1: Data
    var exponent2: Data
    var coefficient: Data

    init(
        modulus: Data,
        publicExponent: Data,
        privateExponent: Data,
        prime1: Data,
        prime2: Data,
        exponent1: Data,
        exponent2: Data,
        coefficient: Data
    ) {
        self.modulus = modulus
        self.publicExponent = publicExponent
        self.privateExponent = privateExponent
        self.prime1 = prime1
        self.prime2 = prime2
        self.exponent1 = exponent1
        self.exponent2 = exponent2
        self.coefficient = coefficient
    }

    /// Reads the PKCS#1 `RSAPrivateKey` DER that `SecKeyCopyExternalRepresentation`
    /// returns for an RSA key.
    init(pkcs1DER: Data) throws {
        var outer = try DERReader(pkcs1DER)
        var sequence = try outer.readSequence()
        _ = try sequence.readInteger() // version
        modulus = Self.trimmed(try sequence.readInteger())
        publicExponent = Self.trimmed(try sequence.readInteger())
        privateExponent = Self.trimmed(try sequence.readInteger())
        prime1 = Self.trimmed(try sequence.readInteger())
        prime2 = Self.trimmed(try sequence.readInteger())
        exponent1 = Self.trimmed(try sequence.readInteger())
        exponent2 = Self.trimmed(try sequence.readInteger())
        coefficient = Self.trimmed(try sequence.readInteger())
    }

    /// The `ssh-rsa AAAA… comment` line used in `authorized_keys`.
    func publicKeyLine(comment: String) -> String {
        let name = comment.trimmingCharacters(in: .whitespacesAndNewlines)
        let line = "ssh-rsa \(publicKeyBlob().base64EncodedString())"
        return name.isEmpty ? line : "\(line) \(name)"
    }

    func publicKeyBlob() -> Data {
        var blob = Data()
        blob.append(Self.sshString(Data("ssh-rsa".utf8)))
        blob.append(Self.mpint(publicExponent))
        blob.append(Self.mpint(modulus))
        return blob
    }

    /// OpenSSH's `openssh-key-v1` container, unencrypted (cipher and KDF
    /// "none"), which is what the app stores in the Keychain.
    func opensshPrivateKey(comment: String) throws -> String {
        let check = UInt32.random(in: .min ... .max)
        var privateBlob = Data()
        privateBlob.append(Self.uint32(check))
        privateBlob.append(Self.uint32(check))
        privateBlob.append(Self.sshString(Data("ssh-rsa".utf8)))
        privateBlob.append(Self.mpint(modulus))
        privateBlob.append(Self.mpint(publicExponent))
        privateBlob.append(Self.mpint(privateExponent))
        privateBlob.append(Self.mpint(coefficient))
        privateBlob.append(Self.mpint(prime1))
        privateBlob.append(Self.mpint(prime2))
        privateBlob.append(Self.sshString(Data(comment.utf8)))

        var padding: UInt8 = 1
        while privateBlob.count % 8 != 0 {
            privateBlob.append(padding)
            padding &+= 1
        }

        var payload = Data("openssh-key-v1\u{0}".utf8)
        payload.append(Self.sshString(Data("none".utf8)))
        payload.append(Self.sshString(Data("none".utf8)))
        payload.append(Self.sshString(Data()))
        payload.append(Self.uint32(1))
        payload.append(Self.sshString(publicKeyBlob()))
        payload.append(Self.sshString(privateBlob))

        let encoded = payload.base64EncodedString()
        let wrapped = stride(from: 0, to: encoded.count, by: 70).map { start -> Substring in
            let from = encoded.index(encoded.startIndex, offsetBy: start)
            let to = encoded.index(from, offsetBy: min(70, encoded.count - start))
            return encoded[from..<to]
        }.joined(separator: "\n")
        return "-----BEGIN OPENSSH PRIVATE KEY-----\n\(wrapped)\n-----END OPENSSH PRIVATE KEY-----\n"
    }

    /// Creates an RSA private key with Security and returns it as OpenSSH text.
    static func generate(bits: Int, comment: String) throws -> String {
        guard [2048, 3072, 4096].contains(bits) else {
            throw SSHKeyFormatError("Unsupported RSA key size.")
        }
        let attributes: [CFString: Any] = [
            kSecAttrKeyType: kSecAttrKeyTypeRSA,
            kSecAttrKeySizeInBits: bits,
            kSecAttrIsPermanent: false,
        ]
        var error: Unmanaged<CFError>?
        guard let key = SecKeyCreateRandomKey(attributes as CFDictionary, &error) else {
            throw SSHKeyFormatError(Self.reason(error, fallback: "The RSA key could not be generated."))
        }
        error = nil
        guard let data = SecKeyCopyExternalRepresentation(key, &error) as Data? else {
            throw SSHKeyFormatError(Self.reason(error, fallback: "The RSA key could not be exported."))
        }
        return try RSAKeyMaterial(pkcs1DER: data).opensshPrivateKey(comment: comment)
    }

    private static func reason(_ error: Unmanaged<CFError>?, fallback: String) -> String {
        guard let error else { return fallback }
        return (error.takeRetainedValue() as NSError).localizedDescription
    }

    private static func trimmed(_ value: Data) -> Data {
        guard let first = value.firstIndex(where: { $0 != 0 }) else { return Data() }
        // Copy out of the slice: Data slices can start above zero, which makes
        // inserting the mpint sign byte at index 0 trap.
        return Data(Array(value[first...]))
    }

    private static func uint32(_ value: UInt32) -> Data {
        withUnsafeBytes(of: value.bigEndian) { Data($0) }
    }

    private static func sshString(_ value: Data) -> Data {
        var data = uint32(UInt32(value.count))
        data.append(value)
        return data
    }

    private static func mpint(_ value: Data) -> Data {
        var bytes = trimmed(value)
        if let first = bytes.first, first & 0x80 != 0 { bytes.insert(0, at: 0) }
        return sshString(bytes)
    }
}

struct SSHKeyFormatError: LocalizedError {
    let message: String

    init(_ message: String) { self.message = message }

    var errorDescription: String? { message }
}

private struct DERReader {
    let data: Data
    var index = 0

    init(_ data: Data) { self.data = data }

    mutating func readSequence() throws -> DERReader {
        let (tag, value) = try readTLV()
        guard tag == 0x30 else { throw SSHKeyFormatError("The generated RSA key has an unexpected format.") }
        return DERReader(value)
    }

    mutating func readInteger() throws -> Data {
        let (tag, value) = try readTLV()
        guard tag == 0x02 else { throw SSHKeyFormatError("The generated RSA key has an unexpected format.") }
        return value
    }

    private mutating func readTLV() throws -> (tag: UInt8, value: Data) {
        guard index < data.count else {
            throw SSHKeyFormatError("The generated RSA key is incomplete.")
        }
        let tag = data[index]
        index += 1
        guard index < data.count else {
            throw SSHKeyFormatError("The generated RSA key is incomplete.")
        }
        var length = Int(data[index])
        index += 1
        if length & 0x80 != 0 {
            let count = length & 0x7f
            guard count > 0, count <= 4, index + count <= data.count else {
                throw SSHKeyFormatError("The generated RSA key has an invalid length.")
            }
            length = 0
            for _ in 0..<count {
                length = (length << 8) | Int(data[index])
                index += 1
            }
        }
        guard index + length <= data.count else {
            throw SSHKeyFormatError("The generated RSA key is incomplete.")
        }
        let value = data.subdata(in: index..<(index + length))
        index += length
        return (tag, value)
    }
}
